import{_ as a,o as s,c as t,a0 as l}from"./chunks/framework.DQOulFGV.js";const e="data:image/svg+xml;base64,",I="data:image/svg+xml;base64,",y=JSON.parse('{"title":"第5章 事务与 Lua","description":"","frontmatter":{},"headers":[],"relativePath":"redis/04-high-availability/chapter-05-transaction-lua.md","filePath":"redis/04-high-availability/chapter-05-transaction-lua.md"}'),h={name:"redis/04-high-availability/chapter-05-transaction-lua.md"};function n(d,i,g,p,k,r){return s(),t("div",null,[...i[0]||(i[0]=[l(`<h1 id="第5章-事务与-lua" tabindex="-1">第5章 事务与 Lua <a class="header-anchor" href="#第5章-事务与-lua" aria-label="Permalink to &quot;第5章 事务与 Lua&quot;">​</a></h1><blockquote><p>Redis 的事务与 Lua 脚本都能把多条命令组合起来执行，但机制不同：事务强调「入队后一起执行」，Lua 强调「服务端原子脚本」。本章对比两者，讲清各自适用场景。</p></blockquote><hr><h2 id="_5-1-multi-exec" tabindex="-1">5.1 MULTI / EXEC <a class="header-anchor" href="#_5-1-multi-exec" aria-label="Permalink to &quot;5.1 MULTI / EXEC&quot;">​</a></h2><p>Redis 事务通过 <code>MULTI</code>、<code>EXEC</code>、<code>DISCARD</code> 实现：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MULTI</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 开启事务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 入队</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INCR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 入队</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 入队</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXEC</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 一次性执行所有命令</span></span></code></pre></div><h3 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to &quot;执行流程&quot;">​</a></h3><p><img src="`+e+`" alt="事务 MULTI/EXEC 执行流程"></p><p>事务执行期间，命令不会被其他客户端插队，保证<strong>命令序列的原子执行</strong>。</p><h3 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h3><p>Redis 事务的错误分为两类：</p><table tabindex="0"><thead><tr><th style="text-align:left;">错误类型</th><th style="text-align:left;">触发时机</th><th style="text-align:left;">事务行为</th></tr></thead><tbody><tr><td style="text-align:left;">语法错误</td><td style="text-align:left;">入队时（命令不存在、参数错误）</td><td style="text-align:left;">整个事务不执行</td></tr><tr><td style="text-align:left;">运行时错误</td><td style="text-align:left;">执行时（类型不匹配）</td><td style="text-align:left;">出错命令报错，其他命令继续执行</td></tr></tbody></table><h3 id="不回滚" tabindex="-1">不回滚 <a class="header-anchor" href="#不回滚" aria-label="Permalink to &quot;不回滚&quot;">​</a></h3><p>Redis 事务<strong>不支持回滚</strong>：执行到一半出错，前面已执行的命令不会撤销。这是 Redis 与关系型数据库事务的本质区别——Redis 追求简单高性能，放弃回滚能力。</p><hr><h2 id="_5-2-watch-乐观锁" tabindex="-1">5.2 WATCH 乐观锁 <a class="header-anchor" href="#_5-2-watch-乐观锁" aria-label="Permalink to &quot;5.2 WATCH 乐观锁&quot;">​</a></h2><p><code>WATCH</code> 用于实现乐观锁：监视一个或多个 key，如果这些 key 在 <code>EXEC</code> 前被其他客户端修改，则事务放弃执行。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> balance</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 监视余额</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MULTI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DECRBY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> balance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 扣款</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXEC</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # 若 balance 被改过，返回 nil（放弃）</span></span></code></pre></div><p><img src="`+I+`" alt="WATCH 乐观锁流程"></p><p>适用场景：需要「读-判断-写」一致性的场景，如余额扣减、库存扣减。若并发冲突频繁，WATCH 会大量重试，性能差。</p><hr><h2 id="_5-3-lua-脚本" tabindex="-1">5.3 Lua 脚本 <a class="header-anchor" href="#_5-3-lua-脚本" aria-label="Permalink to &quot;5.3 Lua 脚本&quot;">​</a></h2><p>Lua 脚本在 Redis 服务端执行，整个过程原子，中间不会被其他命令打断。</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 原子扣减库存</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> tonumber</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(redis.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;get&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, KEYS[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> then</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    redis.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;decr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, KEYS[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EVAL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;脚本内容&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stock:1001</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 执行脚本，1 个 key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SCRIPT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;脚本内容&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 缓存脚本，返回 SHA1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EVALSHA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;sha1值&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stock:1001</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 用 SHA1 调用，节省带宽</span></span></code></pre></div><h3 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">要点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">原子执行</td><td style="text-align:left;">脚本执行期间不被打断</td></tr><tr><td style="text-align:left;">redis.call / pcall</td><td style="text-align:left;">调用 Redis 命令，pcall 出错不中断脚本</td></tr><tr><td style="text-align:left;">SCRIPT LOAD</td><td style="text-align:left;">预编译脚本，EVALSHA 复用</td></tr><tr><td style="text-align:left;">随机命令限制</td><td style="text-align:left;">集群下脚本内随机命令（如 SPOP）受限</td></tr></tbody></table><blockquote><p>Lua 脚本相比事务的优势：可以在脚本内做逻辑判断（if/else、循环），而事务只是简单地把命令入队后顺序执行。复杂的「读-判断-写」逻辑用 Lua 更合适。</p></blockquote><hr><h2 id="_5-4-事务与-lua-对比" tabindex="-1">5.4 事务与 Lua 对比 <a class="header-anchor" href="#_5-4-事务与-lua-对比" aria-label="Permalink to &quot;5.4 事务与 Lua 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">事务（MULTI/EXEC）</th><th style="text-align:left;">Lua 脚本</th></tr></thead><tbody><tr><td style="text-align:left;">原子性</td><td style="text-align:left;">命令序列原子执行</td><td style="text-align:left;">脚本整体原子执行</td></tr><tr><td style="text-align:left;">逻辑判断</td><td style="text-align:left;">不支持（只能入队后顺序执行）</td><td style="text-align:left;">支持（if/else/循环）</td></tr><tr><td style="text-align:left;">回滚</td><td style="text-align:left;">不支持</td><td style="text-align:left;">不支持</td></tr><tr><td style="text-align:left;">条件执行</td><td style="text-align:left;">用 WATCH 乐观锁实现</td><td style="text-align:left;">脚本内直接判断</td></tr><tr><td style="text-align:left;">适用场景</td><td style="text-align:left;">简单批量命令</td><td style="text-align:left;">复杂读-判断-写逻辑</td></tr></tbody></table><p>选型建议：只是把多条命令打包执行，用事务；需要根据数据做判断再决定后续操作，用 Lua。</p>`,32)])])}const C=a(h,[["render",n]]);export{y as __pageData,C as default};
